-- Operator-managed qualified cost bounds; no browser/MCP route writes these rows.
CREATE TABLE trusted_fax_tariffs(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), sender_id TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider='telnyx'), account_id TEXT NOT NULL CHECK(length(account_id) BETWEEN 1 AND 200), connection_id TEXT NOT NULL CHECK(length(connection_id) BETWEEN 1 AND 200), destination_prefix TEXT NOT NULL CHECK(length(destination_prefix) BETWEEN 2 AND 16 AND substr(destination_prefix,1,1)='+'), options_json TEXT NOT NULL CHECK(json_valid(options_json)), currency TEXT NOT NULL CHECK(currency='EUR'), base_minor INTEGER NOT NULL CHECK(typeof(base_minor)='integer' AND base_minor BETWEEN 0 AND 1000000), per_page_minor INTEGER NOT NULL CHECK(typeof(per_page_minor)='integer' AND per_page_minor BETWEEN 0 AND 1000000), max_pages INTEGER NOT NULL CHECK(max_pages BETWEEN 1 AND 350), quote_ttl_seconds INTEGER NOT NULL CHECK(quote_ttl_seconds BETWEEN 30 AND 900), cost_basis TEXT NOT NULL CHECK(cost_basis='qualified_upper_bound'), source_reference TEXT NOT NULL CHECK(length(source_reference) BETWEEN 1 AND 500), source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64), valid_from TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>valid_from), status TEXT NOT NULL CHECK(status IN ('qualified','revoked')), created_at TEXT NOT NULL, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,sender_id) REFERENCES senders(organization_id,id));
CREATE UNIQUE INDEX qualified_fax_tariff_route ON trusted_fax_tariffs(organization_id,sender_id,account_id,connection_id,destination_prefix,options_json) WHERE status='qualified';
CREATE TRIGGER immutable_fax_tariff BEFORE UPDATE ON trusted_fax_tariffs WHEN NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.sender_id<>OLD.sender_id OR NEW.provider<>OLD.provider OR NEW.account_id<>OLD.account_id OR NEW.connection_id<>OLD.connection_id OR NEW.destination_prefix<>OLD.destination_prefix OR NEW.options_json<>OLD.options_json OR NEW.currency<>OLD.currency OR NEW.base_minor<>OLD.base_minor OR NEW.per_page_minor<>OLD.per_page_minor OR NEW.max_pages<>OLD.max_pages OR NEW.quote_ttl_seconds<>OLD.quote_ttl_seconds OR NEW.cost_basis<>OLD.cost_basis OR NEW.source_reference<>OLD.source_reference OR NEW.source_sha256<>OLD.source_sha256 OR NEW.valid_from<>OLD.valid_from OR NEW.expires_at<>OLD.expires_at OR NEW.created_at<>OLD.created_at OR (OLD.status='revoked' AND NEW.status<>'revoked') BEGIN SELECT RAISE(ABORT,'immutable_fax_tariff'); END;
ALTER TABLE dispatches ADD COLUMN quote_fingerprint TEXT;
CREATE TRIGGER immutable_dispatch_quote BEFORE UPDATE ON dispatches WHEN NEW.quote_fingerprint IS NOT OLD.quote_fingerprint BEGIN SELECT RAISE(ABORT,'immutable_dispatch_quote'); END;
CREATE TABLE live_fax_quotes(dispatch_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, tariff_id TEXT NOT NULL, fingerprint TEXT NOT NULL, dispatch_fingerprint TEXT NOT NULL, input_json TEXT NOT NULL CHECK(json_valid(input_json)), input_fingerprint TEXT NOT NULL, account_id TEXT NOT NULL, connection_id TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor BETWEEN 0 AND 1000000), ceiling_minor INTEGER NOT NULL CHECK(typeof(ceiling_minor)='integer' AND ceiling_minor BETWEEN amount_minor AND 1000000), currency TEXT NOT NULL CHECK(currency='EUR'), source_reference TEXT NOT NULL, source_sha256 TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>created_at), FOREIGN KEY(organization_id,dispatch_id) REFERENCES dispatches(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,tariff_id) REFERENCES trusted_fax_tariffs(organization_id,id));
CREATE TRIGGER immutable_live_fax_quote BEFORE UPDATE ON live_fax_quotes BEGIN SELECT RAISE(ABORT,'immutable_live_fax_quote'); END;
CREATE VIEW valid_live_fax_quotes AS SELECT q.*,t.valid_from AS tariff_valid_from,t.expires_at AS tariff_expires_at FROM live_fax_quotes q JOIN dispatches d ON d.organization_id=q.organization_id AND d.id=q.dispatch_id JOIN trusted_fax_tariffs t ON t.organization_id=q.organization_id AND t.id=q.tariff_id JOIN documents doc ON doc.organization_id=d.organization_id AND doc.id=d.document_id JOIN senders s ON s.organization_id=d.organization_id AND s.id=d.sender_id WHERE d.mode='production' AND d.channel='fax' AND d.quote_fingerprint=q.fingerprint AND d.fingerprint=q.dispatch_fingerprint AND t.status='qualified' AND t.provider='telnyx' AND t.sender_id=d.sender_id AND s.status='verified' AND s.mode='production' AND s.channel='fax' AND s.address=d.sender_address AND doc.status='ready' AND doc.pages<=t.max_pages AND t.account_id=q.account_id AND t.connection_id=q.connection_id AND t.options_json=d.options_json AND substr(json_extract(d.recipient_json,'$.phone'),1,length(t.destination_prefix))=t.destination_prefix AND q.amount_minor=t.base_minor+t.per_page_minor*doc.pages AND q.amount_minor=d.estimated_minor AND q.ceiling_minor=d.ceiling_minor AND q.currency=d.currency AND q.source_reference=t.source_reference AND q.source_sha256=t.source_sha256 AND q.expires_at<=t.expires_at AND json_extract(q.input_json,'$.channel')=d.channel AND json_extract(q.input_json,'$.recipient')=d.recipient_json AND json_extract(q.input_json,'$.documentId')=doc.id AND json_extract(q.input_json,'$.documentSha256')=doc.sha256 AND json_extract(q.input_json,'$.senderId')=s.id AND json_extract(q.input_json,'$.senderAddress')=s.address AND json_extract(q.input_json,'$.subject') IS d.subject AND json_extract(q.input_json,'$.html') IS d.html AND json_extract(q.input_json,'$.text') IS d.text AND json_extract(q.input_json,'$.options')=d.options_json AND json_extract(q.input_json,'$.campaignId') IS d.campaign_id AND json_extract(q.input_json,'$.estimatedMinor')=d.estimated_minor AND json_extract(q.input_json,'$.ceilingMinor')=d.ceiling_minor AND json_extract(q.input_json,'$.currency')=d.currency AND json_extract(q.input_json,'$.mode')=d.mode AND NOT EXISTS(SELECT 1 FROM trusted_fax_tariffs newer WHERE newer.organization_id=t.organization_id AND newer.sender_id=t.sender_id AND newer.account_id=t.account_id AND newer.connection_id=t.connection_id AND newer.options_json=t.options_json AND newer.status='qualified' AND length(newer.destination_prefix)>length(t.destination_prefix) AND substr(json_extract(d.recipient_json,'$.phone'),1,length(newer.destination_prefix))=newer.destination_prefix);
CREATE TRIGGER approval_live_fax_quote_insert BEFORE INSERT ON approvals WHEN EXISTS(SELECT 1 FROM dispatches WHERE organization_id=NEW.organization_id AND id=NEW.dispatch_id AND mode='production' AND channel='fax') BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_fax_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND dispatch_fingerprint=NEW.fingerprint AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND tariff_valid_from<=NEW.created_at AND tariff_expires_at>NEW.created_at); END;
CREATE TRIGGER approval_live_fax_quote_update BEFORE UPDATE ON approvals WHEN EXISTS(SELECT 1 FROM dispatches WHERE organization_id=NEW.organization_id AND id=NEW.dispatch_id AND mode='production' AND channel='fax') BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_fax_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND dispatch_fingerprint=NEW.fingerprint AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND tariff_valid_from<=NEW.created_at AND tariff_expires_at>NEW.created_at); END;
CREATE TRIGGER acceptance_live_fax_quote BEFORE UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' AND NEW.mode='production' AND NEW.channel='fax' BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_fax_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND created_at<=NEW.updated_at AND expires_at>NEW.updated_at AND tariff_valid_from<=NEW.updated_at AND tariff_expires_at>NEW.updated_at); END;
CREATE TRIGGER preflight_live_fax_quote BEFORE UPDATE OF status ON dispatches WHEN OLD.status='queued' AND NEW.status='submitting' AND NEW.mode='production' AND NEW.channel='fax' BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NEW.provider IS NOT 'telnyx' OR NOT EXISTS(SELECT 1 FROM valid_live_fax_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND created_at<=NEW.updated_at AND expires_at>NEW.updated_at AND tariff_valid_from<=NEW.updated_at AND tariff_expires_at>NEW.updated_at); END;
CREATE TRIGGER preparation_live_fax_quote AFTER INSERT ON live_fax_quotes BEGIN SELECT RAISE(ABORT,'live_quote_invalid') WHERE NOT EXISTS(SELECT 1 FROM valid_live_fax_quotes WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.dispatch_id AND created_at<=NEW.created_at AND expires_at>NEW.created_at AND tariff_valid_from<=NEW.created_at AND tariff_expires_at>NEW.created_at); END;
